namespace sv_befa564a582f4d76b511534f0b4bf931.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@using sv_befa564a582f4d76b511534f0b4bf931.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-container">
    @* ── Left Sidebar ── *@
    <aside class="catalog-sidebar">
        <h5 class="mb-3">Filters</h5>

        @* Category checkboxes *@
        <div class="filter-section">
            <h6>Category</h6>
            @if (categories is not null)
            {
                @foreach (var cat in categories)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
                               checked="@selectedCategories.Contains(cat)"
                               @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                        <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
                    </div>
                }
            }
            else
            {
                <p class="text-muted small">Loading…</p>
            }
        </div>

        @* Price range *@
        <div class="filter-section">
            <h6>Price Range</h6>
            <div class="mb-2">
                <label class="form-label small mb-0">Min Price</label>
                <input type="number" class="form-control form-control-sm" min="0" step="0.01"
                       @bind="minPrice" placeholder="0.00" />
            </div>
            <div class="mb-2">
                <label class="form-label small mb-0">Max Price</label>
                <input type="number" class="form-control form-control-sm" min="0" step="0.01"
                       @bind="maxPrice" placeholder="No limit" />
            </div>
        </div>

        @* In Stock Only *@
        <div class="filter-section">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="inStockToggle" @bind="inStockOnly" />
                <label class="form-check-label" for="inStockToggle">In Stock Only</label>
            </div>
        </div>

        @* Action buttons *@
        <div class="d-grid gap-2 mt-3">
            <button class="btn btn-primary btn-sm" @onclick="ApplyFilters" disabled="@isLoading">
                Apply Filters
            </button>
            <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFilters" disabled="@isLoading">
                Clear Filters
            </button>
        </div>
    </aside>

    @* ── Main Content ── *@
    <main class="catalog-main">
        @if (errorMessage is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @errorMessage
            </div>
        }
        else if (isLoading)
        {
            <div class="d-flex justify-content-center align-items-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading…</span>
                </div>
                <span class="ms-3">Loading products…</span>
            </div>
        }
        else if (result is null || result.Items.Count == 0)
        {
            <div class="text-center py-5 text-muted">
                <h5>No products found</h5>
                <p>Try adjusting your filters.</p>
            </div>
        }
        else
        {
            @* Toolbar *@
            <div class="catalog-toolbar">
                <div class="d-flex align-items-center gap-3">
                    <label class="form-label mb-0 text-nowrap">Sort by:</label>
                    <select class="form-select form-select-sm sort-select" value="@sortBy" @onchange="OnSortChanged">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A–Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <span class="text-muted small">
                    Showing @ShowingStart–@ShowingEnd of @result.TotalCount products
                </span>
            </div>

            @* Product Grid *@
            <div class="product-grid">
                @foreach (var product in result.Items)
                {
                    <div class="card product-card" @onclick="() => OnProductClicked(product)">
                        <div class="product-image-placeholder" role="img" aria-label="@product.Name">
                            @product.Name[..1]
                        </div>
                        <div class="card-body d-flex flex-column">
                            <h6 class="card-title mb-1 text-truncate" title="@product.Name">@product.Name</h6>
                            <p class="card-text fw-bold mb-1">@product.Price.ToString("C")</p>
                            <div class="mb-1">
                                <span class="star-rating" title="@($"{product.Rating:F1} out of 5")">@RenderStars(product.Rating)</span>
                            </div>
                            @if (!product.InStock)
                            {
                                <span class="badge bg-danger mb-2">Out of Stock</span>
                            }
                            <button class="btn btn-sm btn-success mt-auto"
                                    disabled="@(!product.InStock)"
                                    @onclick="() => OnAddToCart(product)"
                                    @onclick:stopPropagation="true">
                                Add to Cart
                            </button>
                        </div>
                    </div>
                }
            </div>

            @* Pagination *@
            <nav aria-label="Product pagination" class="mt-4">
                <ul class="pagination justify-content-center">
                    <li class="page-item @(currentPage <= 1 ? "disabled" : "")">
                        <button class="page-link" @onclick="() => GoToPage(currentPage - 1)" disabled="@(currentPage <= 1)">
                            Previous
                        </button>
                    </li>
                    @for (int i = 1; i <= TotalPages; i++)
                    {
                        var pageNum = i;
                        <li class="page-item @(pageNum == currentPage ? "active" : "")">
                            <button class="page-link" @onclick="() => GoToPage(pageNum)">@pageNum</button>
                        </li>
                    }
                    <li class="page-item @(currentPage >= TotalPages ? "disabled" : "")">
                        <button class="page-link" @onclick="() => GoToPage(currentPage + 1)" disabled="@(currentPage >= TotalPages)">
                            Next
                        </button>
                    </li>
                </ul>
            </nav>
        }
    </main>
</div>

@code {
    /// <summary>Raised when a product card is clicked so the parent can navigate to its detail page.</summary>
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }

    // ── State ──
    private List<string>? categories;
    private PagedResult<Product>? result;

    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;

    private bool isLoading;
    private string? errorMessage;

    // ── Computed ──
    private int TotalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / PageSize);

    private int ShowingStart => result is null ? 0 : (result.Page - 1) * result.PageSize + 1;
    private int ShowingEnd => result is null ? 0 : Math.Min(result.Page * result.PageSize, result.TotalCount);

    // ── Lifecycle ──
    protected override async Task OnInitializedAsync()
    {
        try
        {
            isLoading = true;
            var categoriesTask = ProductService.GetCategoriesAsync();
            var searchTask = SearchProducts();
            categories = await categoriesTask;
            await searchTask;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    // ── Search ──
    private async Task SearchProducts()
    {
        var filter = new ProductFilter(
            Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
            MinPrice: minPrice,
            MaxPrice: maxPrice,
            InStockOnly: inStockOnly
        );

        result = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
    }

    // ── Event handlers ──
    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        sortBy = "price_asc";
        currentPage = 1;
        await LoadProducts();
    }

    private async Task OnSortChanged(ChangeEventArgs e)
    {
        sortBy = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await LoadProducts();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > TotalPages) return;
        currentPage = page;
        await LoadProducts();
    }

    private async Task LoadProducts()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            await SearchProducts();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task OnProductClicked(Product product)
    {
        if (OnProductSelected.HasDelegate)
            await OnProductSelected.InvokeAsync(product);
    }

    private void OnAddToCart(Product product)
    {
        // Placeholder – wire up cart service here
    }

    // ── Helpers ──
    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

/* ── Layout ── */
.catalog-container {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

.catalog-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
    padding: 1rem;
    border-right: 1px solid #dee2e6;
}

.catalog-main {
    flex: 1 1 75%;
    min-width: 0;
}

/* ── Filter sections ── */
.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h6 {
    margin-bottom: 0.5rem;
    font-weight: 600;
}

/* ── Toolbar ── */
.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.5rem 0;
    border-bottom: 1px solid #dee2e6;
}

.sort-select {
    width: auto;
    min-width: 200px;
}

/* ── Product grid ── */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1rem;
}

.product-card {
    cursor: pointer;
    transition: box-shadow 0.2s, transform 0.15s;
}

.product-card:hover {
    box-shadow: 0 4px 12px rgba(0,0,0,.12);
    transform: translateY(-2px);
}

/* ── Image placeholder ── */
.product-image-placeholder {
    height: 160px;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: #e9ecef;
    color: #6c757d;
    font-size: 3rem;
    font-weight: 700;
    user-select: none;
    border-bottom: 1px solid #dee2e6;
}

/* ── Stars ── */
.star-rating {
    color: #ffc107;
    letter-spacing: 1px;
    font-size: 0.95rem;
}

