@code {
    /// <summary>Raised when a product card is clicked so the parent can navigate to its detail page.</summary>
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }

    // ── State ──
    private List<string>? categories;
    private PagedResult<Product>? result;

    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;

    private bool isLoading;
    private string? errorMessage;

    // ── Computed ──
    private int TotalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / PageSize);

    private int ShowingStart => result is null ? 0 : (result.Page - 1) * result.PageSize + 1;
    private int ShowingEnd => result is null ? 0 : Math.Min(result.Page * result.PageSize, result.TotalCount);

    // ── Lifecycle ──
    protected override async Task OnInitializedAsync()
    {
        try
        {
            isLoading = true;
            var categoriesTask = ProductService.GetCategoriesAsync();
            var searchTask = SearchProducts();
            categories = await categoriesTask;
            await searchTask;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    // ── Search ──
    private async Task SearchProducts()
    {
        var filter = new ProductFilter(
            Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
            MinPrice: minPrice,
            MaxPrice: maxPrice,
            InStockOnly: inStockOnly
        );

        result = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
    }

    // ── Event handlers ──
    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        sortBy = "price_asc";
        currentPage = 1;
        await LoadProducts();
    }

    private async Task OnSortChanged(ChangeEventArgs e)
    {
        sortBy = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await LoadProducts();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > TotalPages) return;
        currentPage = page;
        await LoadProducts();
    }

    private async Task LoadProducts()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            await SearchProducts();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task OnProductClicked(Product product)
    {
        if (OnProductSelected.HasDelegate)
            await OnProductSelected.InvokeAsync(product);
    }

    private void OnAddToCart(Product product)
    {
        // Placeholder – wire up cart service here
    }

    // ── Helpers ──
    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

