+        await LoadProducts();
+    }
+
+    private async Task GoToPage(int page)
+    {
+        if (page < 1 || page > TotalPages) return;
+        currentPage = page;
+        await LoadProducts();
+    }
+
+    private async Task LoadProducts()
+    {
+        try
+        {
+            isLoading = true;
+            errorMessage = null;
+            await SearchProducts();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private void ToggleCategory(string category, bool isChecked)
+    {
+        if (isChecked)
+            selectedCategories.Add(category);
+        else
+            selectedCategories.Remove(category);
+    }
+
+    private async Task OnProductClicked(Product product)
+    {
+        if (OnProductSelected.HasDelegate)
+            await OnProductSelected.InvokeAsync(product);
+    }
+
+    private void OnAddToCart(Product product)
+    {
+        // Placeholder – wire up cart service here
+    }
+
+    // ── Helpers ──
+    private static string RenderStars(double rating)
+    {
+        int full = (int)Math.Round(rating);
+        return new string('★', full) + new string('☆', 5 - full);
+    }
+}
+

toolArgs.file_text:
/* ── Layout ── */
.catalog-container {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

.catalog-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
    padding: 1rem;
    border-right: 1px solid #dee2e6;
}

.catalog-main {
    flex: 1 1 75%;
    min-width: 0;
}

/* ── Filter sections ── */
.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h6 {
    margin-bottom: 0.5rem;
    font-weight: 600;
}

/* ── Toolbar ── */
.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.5rem 0;
    border-bottom: 1px solid #dee2e6;
}

.sort-select {
    width: auto;
    min-width: 200px;
}

/* ── Product grid ── */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1rem;
}

.product-card {
    cursor: pointer;
    transition: box-shadow 0.2s, transform 0.15s;
}

.product-card:hover {
    box-shadow: 0 4px 12px rgba(0,0,0,.12);
    transform: translateY(-2px);
}

/* ── Image placeholder ── */
.product-image-placeholder {
    height: 160px;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: #e9ecef;
    color: #6c757d;
    font-size: 3rem;
    font-weight: 700;
    user-select: none;
    border-bottom: 1px solid #dee2e6;
}

/* ── Stars ── */
.star-rating {
    color: #ffc107;
    letter-spacing: 1px;
    font-size: 0.95rem;
}

